import{_ as s,a0 as a,w as i,s as g,ao as l,I as p,x as e,a1 as n,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const M=JSON.parse('{"title":"迁移LVM分区到新的逻辑卷/驱动器（第六部分） | LCTT x X-CMD","titleTemplate":false,"description":"迁移LVM分区到新的逻辑卷/驱动器（第六部分） | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"迁移LVM分区到新的逻辑卷/驱动器（第六部分） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"迁移LVM分区到新的逻辑卷/驱动器（第六部分） | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141013 Migrating LVM Partitions to New Logical Volume (Drive)--Part VI","title":"迁移LVM分区到新的逻辑卷/驱动器（第六部分）","tag":"201412","desc":""},"relativePath":"201412/20141013 Migrating LVM Partitions to New Logical Volume (Drive)--Part VI.md","filePath":"[post].md"}'),m={name:"201412/20141013 Migrating LVM Partitions to New Logical Volume (Drive)--Part VI.md"};function d(c,t,v,h,w,u){const o=a("Link");return i(),g("div",null,[t[13]||(t[13]=l(`<h1 id="迁移lvm分区到新的逻辑卷-驱动器-第六部分" tabindex="-1">迁移LVM分区到新的逻辑卷/驱动器（第六部分） <a class="header-anchor" href="#迁移lvm分区到新的逻辑卷-驱动器-第六部分" aria-label="Permalink to “迁移LVM分区到新的逻辑卷/驱动器（第六部分）”">​</a></h1><p>这是我们正在进行的LVM系列的第六部分。在本文中，我们将为大家展示怎样在线将现存的逻辑卷迁移到其它新的驱动器。在开始之前，我想要先来介绍一下LVM迁移及其特性。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/LVM-Migrations.png" alt="LVM Storage Migration"></p><p><em>LVM存储迁移</em></p><h3 id="什么是lvm迁移" tabindex="-1">什么是LVM迁移？ <a class="header-anchor" href="#什么是lvm迁移" aria-label="Permalink to “什么是LVM迁移？”">​</a></h3><p><strong>LVM</strong>迁移是LVM众多优秀特性之一，通过它，我们可以迁移逻辑卷到一个新的磁盘而不会丢失数据，也不用关机操作。该特性的功能是将数据从旧磁盘移动到新磁盘。通常，我们只是在一些磁盘发生错误时，才将数据从一个磁盘迁移到另外一个磁盘存储。</p><h3 id="迁移特性" tabindex="-1">迁移特性 <a class="header-anchor" href="#迁移特性" aria-label="Permalink to “迁移特性”">​</a></h3><ul><li>将逻辑卷从一个磁盘移动到另一个磁盘。</li><li>我们可以使用任何类型的磁盘，如SATA、SSD、SAS、SAN storage iSCSI或者FC。</li><li>在线迁移磁盘，而且数据不会丢失。</li></ul><p>在LVM迁移中，我们将交换各个卷、文件系统以及位于已有的存储中的数据。例如，如果我们有一个单一逻辑卷，它已经映射到了物理卷，而该物理卷是一个物理硬盘驱动器。</p><p>现在，如果我们需要升级服务器存储为SSD硬盘驱动器，我们首先需要考虑什么？重新格式化磁盘？不！我们不必重新格式化服务器，LVM可以选择将这些旧的SATA驱动器上的数据迁移到新的SSD驱动器上。在线迁移将会支持任何类型的磁盘，不管是本地驱动器，还是SAN或者光纤通道都可以。</p><h4 id="我的服务器设置" tabindex="-1">我的服务器设置 <a class="header-anchor" href="#我的服务器设置" aria-label="Permalink to “我的服务器设置”">​</a></h4><pre><code>操作系统：	 CentOS 6.5 Final
IP地址：	  192.168.0.224
系统主机名：	lvmmig.tecmintlocal.com
</code></pre><h3 id="步骤1-检查当前驱动器" tabindex="-1">步骤1： 检查当前驱动器 <a class="header-anchor" href="#步骤1-检查当前驱动器" aria-label="Permalink to “步骤1： 检查当前驱动器”">​</a></h3><p><strong>1.</strong>假设我们已经有一个名为“<strong>vdb</strong>”的虚拟驱动器，它已经被映射到了其中一个逻辑卷“<strong>tecmint_lv</strong>”。现在，我们想要迁移“<strong>vdb</strong>”这个逻辑卷到其它某个新的存储设备中。在开始之前，首先在下面所示的<strong>fdisk</strong>和lvs命令的帮助下验证该虚拟驱动器。</p><pre><code># fdisk -l | grep vd
# lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-Logical-Volume-Disk.png" alt="Check Logical Volume Disk"></p><p><em>检查逻辑卷磁盘</em></p><h3 id="步骤2-检查新添加的驱动器" tabindex="-1">步骤2： 检查新添加的驱动器 <a class="header-anchor" href="#步骤2-检查新添加的驱动器" aria-label="Permalink to “步骤2： 检查新添加的驱动器”">​</a></h3><p><strong>2.</strong>在我们确认了现存驱动器后，现在是时候来将新的SSD驱动器连接到系统并在fdisk命令的帮助下验证新添加的驱动器了。</p><pre><code># fdisk -l | grep dev
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-New-Added-Drive.png" alt="Check New Added Drive"></p><p><em>检查新添加的驱动器</em></p><p><strong>注意</strong>：你看到上面屏幕中的内容了吗？新的驱动器已经被成功添加了，其名称为“<strong>/dev/sda</strong>”。</p><h3 id="步骤3-检查当前逻辑和物理卷" tabindex="-1">步骤3： 检查当前逻辑和物理卷 <a class="header-anchor" href="#步骤3-检查当前逻辑和物理卷" aria-label="Permalink to “步骤3： 检查当前逻辑和物理卷”">​</a></h3><p><strong>3.</strong>现在，让我们开始创建物理卷、卷组和逻辑卷以用于迁移。在创建卷时，确保检查<strong>/mnt/lvm</strong>挂载点下的当前逻辑卷的数据。用以下命令来列出挂载点并检查数据。</p><pre><code># df -h
# cd /mnt/lvm
# cat tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-Logical-Volume-Data.png" alt="Check Logical Volume Data"></p><p><em>检查逻辑卷数据</em></p><p><strong>注意</strong>：出于演示的目的，我们已经在<strong>/mnt/lvm</strong>挂载点下创建了两个文件，我们将在线将这些数据迁移到新的驱动器中。</p><p><strong>4.</strong>在迁移之前，确保对确认与物理卷相关的逻辑卷和卷组名称，并且确认哪个物理卷用于容纳该卷组和逻辑卷。</p><pre><code># lvs
# vgs -o+devices | grep tecmint_vg
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Confirm-Logical-Volume-Names.png" alt="Confirm Logical Volume Names"></p><p><em>确认逻辑卷名称</em></p><p><strong>注意</strong>：看到上面屏幕中的内容了吗？“<strong>vdb</strong>”容纳了卷组<strong>tecmint_vg</strong>。</p><h3 id="步骤4-创建新物理卷" tabindex="-1">步骤4： 创建新物理卷 <a class="header-anchor" href="#步骤4-创建新物理卷" aria-label="Permalink to “步骤4： 创建新物理卷”">​</a></h3><p><strong>5.</strong>在在我们新添加的SSD驱动器中创建物理卷之前，我们需要使用fdisk来定义分区。在创建分区时，别忘了修改分区类型为LVM（8e）。</p><pre><code># pvcreate /dev/sda1 -v
# pvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-Physical-Volume.png" alt="Create Physical Volume"></p><p><em>创建物理卷</em></p><p><strong>6.</strong>接下来，使用‘vgextend命令’来添加新创建的物理卷到现存卷组tecmint_vg。</p><pre><code># vgextend tecmint_vg /dev/sda1
# vgs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Add-Physical-Volume.png" alt="Add Physical Volume"></p><p><em>添加物理卷</em></p><p><strong>7.</strong>要获得卷组的完整信息列表，请使用‘vgdisplay’命令。</p><pre><code># vgdisplay tecmint_vg -v
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/List-Volume-Group-Info.png" alt="List Volume Group Info"></p><p><em>列出卷组信息</em></p><p><strong>注意</strong>：在上面屏幕中，我们可以看到在输出结果的结束处，我们的PV已经添加到了卷组中。</p><p><strong>8.</strong>如果我们需要知道更多关于哪些设备被映射的信息，请使用‘<strong>dmsetup</strong>’依赖命令。</p><pre><code># lvs -o+devices
# dmsetup deps /dev/tecmint_vg/tecmint_lv
</code></pre><p>在上面的结果中，有个<strong>1个</strong>依赖（PV）或（驱动器），而这里<strong>17</strong>被列出了。如果你想要检查设备，那些关联的有着主、次设备号的驱动器，以确认，使用下面的命令。</p><pre><code># ls -l /dev | grep vd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/List-Device-Information.png" alt="List Device Information"></p><p><em>列出设备信息</em></p><p><strong>注意</strong>：在上面的命令中，我们可以看到主设备号是<strong>252</strong>，次设备号是<strong>17</strong>，它连接到了<strong>vdb1</strong>。希望你理解了上面命令的输出。</p><h3 id="步骤5-lvm镜像法" tabindex="-1">步骤5： LVM镜像法 <a class="header-anchor" href="#步骤5-lvm镜像法" aria-label="Permalink to “步骤5： LVM镜像法”">​</a></h3><p><strong>9.</strong>现在，该使用镜像法来进行迁移了。使用‘<strong>lvconvert</strong>’命令来将数据从旧逻辑卷迁移到新驱动器。</p><pre><code># lvconvert -m 1 /dev/tecmint_vg/tecmint_lv /dev/sda1
</code></pre><ul><li><strong>-m</strong> = 镜像</li><li><strong>1</strong> = 添加单个镜像</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Mirroring-Method-Migration.png" alt="Mirroring Method Migration"></p><p><em>镜像法迁移</em></p><p><strong>注意</strong>：上面的迁移过程根据卷的大小会花费一段时间。</p><p><strong>10.</strong>在迁移过程完成后，验证转换的镜像。</p><pre><code># lvs -o+devices
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-Converted-Mirror.png" alt="Verify Converted Mirror"></p><p><em>验证转换的镜像</em></p><p><strong>11.</strong>当你确认转换的镜像没有任何问题后，你可以移除旧的虚拟磁盘<strong>vdb1</strong>。<strong>-m</strong>选项将移除镜像，先前我们使用<strong>l</strong>来添加镜像。</p><pre><code># lvconvert -m 0 /dev/tecmint_vg/tecmint_lv /dev/vdb1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Remove-Virtual-Disk.png" alt="Remove Virtual Disk"></p><p><em>移除虚拟磁盘</em></p><p><strong>12.</strong>在旧虚拟磁盘移除后，你可以使用以下命令来再次检查逻辑卷设备。</p><pre><code># lvs -o+devices
# dmsetup deps /dev/tecmint_vg/tecmint_lv
# ls -l /dev | grep sd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-New-Mirrored-Device.png" alt="Check New Mirrored Device"></p><p><em>检查新镜像的设备</em></p><p>在上面的图片中，你看到了吗？我们的逻辑卷现在依赖于<strong>8,1</strong>，名称为<strong>sda1</strong>。这说明我们的迁移过程已经完成了。</p><p><strong>13.</strong>现在验证我们从旧驱动器上迁移过来的文件。如果在新驱动器中的数据与原数据一样，那就说明我们每一步都完成得很完美。</p><pre><code># cd /mnt/lvm/
# cat tecmin.txt 
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-Mirrored-Data.png" alt="Check Mirrored Data"></p><p><em>检查镜像的数据</em></p><pre><code># vgreduce /dev/tecmint_vg /dev/vdb1
# vgs -o+devices
</code></pre><p><strong>14.</strong>在所有的都被完美创建后，现在该从卷组中删除<strong>vdb1</strong>并进行再次确认，哪些设备依赖于我们的卷组。</p><p><strong>15.</strong>在从卷组<strong>tecmint_vg</strong>移除vdb1后，我们的逻辑卷还在那儿，因为我们已经将它从<strong>vdb1</strong>迁移到了<strong>sda1</strong>。</p><pre><code># lvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Delete-Virtual-Disk.png" alt="Delete Virtual Disk"></p><p><em>删除虚拟磁盘</em></p><h3 id="步骤6-lvm-pvmove镜像法" tabindex="-1">步骤6： LVM pvmove镜像法 <a class="header-anchor" href="#步骤6-lvm-pvmove镜像法" aria-label="Permalink to “步骤6： LVM pvmove镜像法”">​</a></h3><p><strong>16.</strong>我们可以使用带有‘<strong>-n</strong>’（逻辑卷名称）选项的‘<strong>pvmove</strong>’命令来取代‘<strong>lvconvert</strong>’镜像命令，在两个设备间进行数据镜像。</p><pre><code># pvmove -n /dev/tecmint_vg/tecmint_lv /dev/vdb1 /dev/sda1
</code></pre><p>该命令是在两个设备间镜像数据的最简单的一个，但是在真实环境中，<strong>镜像</strong>比<strong>pvmove</strong>使用得更为频繁。</p><h3 id="结尾" tabindex="-1">结尾 <a class="header-anchor" href="#结尾" aria-label="Permalink to “结尾”">​</a></h3><p>在本文中，我们介绍了怎样将逻辑卷从一个驱动器迁移到另一个驱动器。希望你已经掌握了逻辑卷管理中这一新的技巧。对于该配置，必须建立在掌握逻辑卷管理基础技能的基础上。对于基础配置，请参阅本文顶部需求章节中提供的链接。</p><hr>`,92)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"http://www.tecmint.com/lvm-storage-migration/#comment-331336"},{default:r(()=>[...t[0]||(t[0]=[e("http://www.tecmint.com/lvm-storage-migration/#comment-331336",-1)])]),_:1})]),p("p",null,[t[5]||(t[5]=e("作者：",-1)),n(o,{href:"http://www.tecmint.com/author/babinlonston/"},{default:r(()=>[...t[2]||(t[2]=[e("Babin Lonston",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),n(o,{href:"https://github.com/GOLinux"},{default:r(()=>[...t[3]||(t[3]=[e("GOLinux",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:r(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[10]||(t[10]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创翻译，",-1)),n(o,{href:"http://linux.cn/"},{default:r(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const f=s(m,[["render",d]]);export{M as __pageData,f as default};
